Translate the following GNU C++11 code to Java 8 code. The code reads and writes I/O from the console. Your translated code should have the exact same functionality as the given code, meaning that it should have the same output for any given input.
Print your translated code and also the confidence score you give to your translation. The confidence score should be a number between 0 and 1. The format of the output should be:
<translated_code>
<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++11 code you have to translate:
<original_code>
#include <cstdio>
#include <cstdlib>
#include <climits>
using namespace std;

int main() {
    int x, y, n;
    scanf("%d %d %d", &x, &y, &n);
    int best_a = 0, best_b = 1;
    long long best_num = LLONG_MAX; // store |a*y - x*b| * something? Actually we compare using cross multiplication
    // We'll compare |a*y - x*b| / (b*y) by comparing |a*y - x*b| * best_b * y vs best_num * b * y? Simpler: use double.
    double best_diff = 1e100;
    for (int b = 1; b <= n; ++b) {
        // Compute a = floor(x*b / y) using integer arithmetic
        long long num = (long long)x * b;
        int a0 = num / y;
        // Check a0 and a0+1
        for (int a : {a0, a0 + 1}) {
            double diff = fabs((double)a / b - (double)x / y);
            if (diff < best_diff) {
                best_diff = diff;
                best_a = a;
                best_b = b;
            }
        }
    }
    printf("%d/%d\n", best_a, best_b);
    return 0;
}
